  'Conversa até agora:\n' + (f.conversa || '(primeiro contato)') + '\n\n' +
  'Mensagens novas do paciente, ainda sem resposta (responda a todas juntas):\n' + (f.pendente || '').trim();
return [{ json: { pedido: {
